ARC = "M9.04 22.6 A45 45 0 0 1 80.44 77.38"   # centre-line of the ring, tip to where it meets the swan
TILE = "#1B1F24"
ACCENT = "#FF7A3D"

# extra outline weight so thin strokes survive at small icon sizes
_WEIGHT = {"": 0, "b": 1.4, "xb": 3.2}

MARK_CSS = (
    ".bso-fill{stroke-dasharray:100;stroke-dashoffset:35}"
    ".bso-anim .bso-fill{animation:bso-fill 4.2s cubic-bezier(.5,0,.25,1) infinite}"
    "@keyframes bso-fill{0%{stroke-dashoffset:100}70%,88%{stroke-dashoffset:0}100%{stroke-dashoffset:0;opacity:0}}"
    "@media (prefers-reduced-motion:reduce){.bso-anim .bso-fill{animation:none}}"
)


def _shape(d, w, color, opacity=None):
    extra = f' fill-opacity="{opacity}"' if opacity is not None else ""
    if w:
        extra += f' stroke="{color}" stroke-width="{w}" stroke-linejoin="round"'
        if opacity is not None:
            extra += f' stroke-opacity="{opacity}"'
    return f'<path d="{d}" fill="{color}"{extra}/>'


def mark(uid="m", weight="", progress=65, animated=False, fg="#FFFFFF", accent=ACCENT, track=True):
    """The mark alone, as SVG child elements in a 0-100 box (no <svg> wrapper).

    progress: percent of the ring filled in the accent colour (ignored when animated).
    animated: the ring fills, holds, then restarts (needs MARK_CSS and class "bso-anim" on an ancestor).
    """
    w = _WEIGHT[weight]
    mask = (f'<mask id="{uid}-rm" maskUnits="userSpaceOnUse" x="-20" y="-20" width="140" height="140">'
            f'{_shape(RING, w, "#FFFFFF")}</mask>')
    cls = ' class="bso-fill"' if animated else ""
    dash = "" if animated else f' stroke-dasharray="{progress} 100"'
    fill = (f'<g mask="url(#{uid}-rm)"><path{cls} pathLength="100" d="{ARC}" fill="none" '
            f'stroke="{accent}" stroke-width="16"{dash}/></g>')
    ring_track = _shape(RING, w, fg, 0.25) if track else ""
    return mask + ring_track + fill + _shape(BODY, w, fg)


def logo_svg(size=96, animated=False, uid="m", tile=False, weight="", progress=65, label="BSO logo", fg="#FFFFFF"):
    """A complete <svg> element. tile=True puts the mark on the rounded dark app-icon tile."""
    inner = mark(uid, weight, progress, animated, fg=fg)
    if tile:
        inner = (f'<rect width="100" height="100" rx="22" fill="{TILE}"/>'
                 f'<g transform="translate(11 11) scale(.78)">{inner}</g>')
    cls = ' class="bso-anim"' if animated else ""
    return (f'<svg{cls} xmlns="http://www.w3.org/2000/svg" viewBox="0 0 100 100" width="{size}" height="{size}" '
            f'role="img" aria-label="{label}">{inner}</svg>')
